/**
 * The ng-prism symbol as the styleguide draws it: the logo in the header, the
 * sidebar footer and the empty state, and the favicon. A verbatim copy of
 * `docs/assets/brand/ng-prism-symbol.svg`, which `brand-image.spec.ts` checks;
 * replace both together.
 *
 * Kept as data rather than an asset file so a consuming app needs no asset
 * path. The symbol is a detailed raster image inside an SVG, so it is drawn
 * through an `<img>` and is the same data URI everywhere.
 */
export const BRAND_IMAGE_SVG =
    '<svg xmlns="http://www.w3.org/2000/svg" version="1.1" xmlns:xlink="http://www.w3.org/1999/xlink" width="556" height="437" viewBox="0 0 556 437"><metadata><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#" xmlns:dc="http://purl.org/dc/elements/1.1/"><rdf:Description><dc:creator>RealFaviconGenerator</dc:creator><dc:source>https://realfavicongenerator.net</dc:source></rdf:Description></rdf:RDF></metadata><image width="556" height="437" xlink:href="data:image/png;base64,"></image><style>@media (prefers-color-scheme: light) { :root { filter: none; } }\n@media (prefers-color-scheme: dark) { :root { filter: none; } }\n</style></svg>';

/** The symbol's intrinsic size; the logo derives its width from the height it is given. */
export const BRAND_IMAGE_WIDTH = 556;
export const BRAND_IMAGE_HEIGHT = 437;

/** The symbol as an `image/svg+xml` data URI, for an `<img>` and for the favicon. */
export const BRAND_IMAGE_DATA_URI = `data:image/svg+xml,${encodeURIComponent(BRAND_IMAGE_SVG)}`;
